#include "v3_scenarios.hpp"
void recovery_detail(bool curve,double common_y){auto f=configured(true);f.through(399);double maxstep=0.,maxcorrection=0.,firstgood=-1.,error2s=-1.;Vec3 previous{},previous_truth{};bool have=false;for(int i=400;i<=1480;++i){I t=T0+i*DT;double s=(i-400)*.25;auto truth=curve?returning(s):fake(s);auto measured=truth;if(i>=1080)measured.p[1]+=common_y;if((i<=560||i>=1080)&&i%2==0)for(int ch=0;ch<2;++ch)require(f.pipe.fix(ch,t,t,obs(measured,ch)),"recovery detail fix");auto o=f.tick(i);double error=norm(sub(o.position,truth.p));if(i>=1080){if(firstgood<0&&error<1.)firstgood=(i-1080)*.05;if(i==1120)error2s=error;if(have){maxstep=std::max(maxstep,norm(sub(o.position,previous)));maxcorrection=std::max(maxcorrection,norm(sub(sub(o.position,previous),sub(truth.p,previous_truth))));}if(i==1080||i==1120||i==1280||i==1480)std::cout<<"recovery_detail curve="<<curve<<" common_y="<<common_y<<" tick="<<i<<" error="<<error<<" flags="<<o.flags<<" accepted="<<o.gnss_accepted<<" rejected="<<o.gnss_rejected<<"\n";}previous=o.position;previous_truth=truth.p;have=true;}std::cout<<"SUMMARY recovery_detail curve="<<curve<<" common_y="<<common_y<<" first_below1_seconds="<<firstgood<<" error_at2s="<<error2s<<" maxstep="<<maxstep<<" maxcorrection="<<maxcorrection<<"\n";}
void episode(bool continuous){auto f=configured(true);f.through(379);I t=T0+380*DT;for(int ch=0;ch<2;++ch)require(f.pipe.fix(ch,t,t,f.fix_lla(ch,t,0.,ch==0?12.:0.)),"episode conflict");require(f.tick(380).flags&1024,"episode conflict flag");int first=-1;Output last;for(int i=381;i<=700;++i){I h=T0+i*DT;if(continuous&&i%2==0){auto wrong=fake((i-380)*.25);wrong.p[0]-=5.;require(f.pipe.fix(0,h,h,obs(wrong,0)),"continuous corrupt fix");}else if(!continuous&&i>=480&&i%2==0){auto true_branch=fake((i-480)*.25);true_branch.p[0]+=20.;require(f.pipe.fix(1,h,h,obs(true_branch,1)),"new episode true fix");}last=f.tick(i);if((last.flags&256)&&first<0)first=i;}std::cout<<"SUMMARY episode continuous="<<continuous<<" first_free="<<first<<" final_flags="<<last.flags<<" accepted="<<last.gnss_accepted<<" rejected="<<last.gnss_rejected<<"\n";require(continuous?(first<0&&(last.flags&1024)):(first>=0&&!(last.flags&1024)),"episode boundary control");}
int main(){std::cout<<std::setprecision(17);v3_scenarios();recovery_detail(true,0.);recovery_detail(true,-2.5);recovery_detail(false,0.);episode(false);episode(true);}
